parameters.jsCode:
const payload = $('payload_webhook').first().json;


// =====================================================
// CONTEÚDO EXTRAÍDO DA MENSAGEM ATUAL
// =====================================================

let leituraImagem = '';

try {
  leituraImagem = $('Analyze image')
    .all()
    .map(item => item.json?.[0]?.content?.[0]?.text || '')
    .filter(Boolean)
    .join('\n\n');
} catch {
  leituraImagem = '';
}


// =====================================================
// TRANSCRIÇÃO DE ÁUDIO
// =====================================================

let textoAudio = '';

try {
  textoAudio =
    $('Transcribe a recording').first().json.text || '';
} catch {
  textoAudio = '';
}


// =====================================================
// TEXTO DE APOIO
// =====================================================

const textoApoio =
  payload.text ||
  payload.caption_image_text ||
  payload.caption_pdf_text ||
  '';


// =====================================================
// MENSAGEM ATUAL NORMALIZADA
// =====================================================

const textoAtual =
  leituraImagem
    ? [textoApoio, leituraImagem]
        .filter(Boolean)
        .join('\n\n')
    : (
        payload.text ||
        textoAudio ||
        payload.caption_pdf_text ||
        payload.caption_image_text ||
        ''
      );


// =====================================================
// CONSULTA DO BUFFER
// =====================================================

const payloadBd = $('payload_bd').first().json;

const itensBuffer = Array.isArray(payloadBd.buffer)
  ? payloadBd.buffer
  : [];

const mensagensBuffer = itensBuffer
  .filter(item =>
    String(item.status_buffer ?? '')
      .trim()
      .toLowerCase() === 'processing'
  )
  .map(item => ({
    row_number: Number(item.row_number),
    message_in: String(item.message_in ?? '').trim()
  }))
  .filter(item =>
    Number.isFinite(item.row_number) &&
    item.message_in !== ''
  )
  .sort((a, b) =>
    a.row_number - b.row_number
  );

// =====================================================
// CONSOLIDAÇÃO DA MENSAGEM
// =====================================================

const text =
  mensagensBuffer.length > 0
    ? [
        ...mensagensBuffer.map(item => item.message_in),
        textoAtual
      ]
        .filter(Boolean)
        .join('\n\n')
    : textoAtual;


// =====================================================
// OUTPUT
// =====================================================


return {
  json: {
    text
  },
  binary: $binary
};

const CONFIG = {
  prescricao_externa: {
    saida: 'prescricao_externa',
    unico: true,
  },
  agendamentos: {
    saida: 'agendamentos',
    unico: false,
  },
  user_atual_state: {
    saida: 'estado',
    unico: true,
  },
  user_profile: {
    saida: 'perfil',
    unico: true,
  },
  events: {
    saida: 'eventos',
    unico: false,
  },
  buffer: {
    saida: 'buffer',
    unico: false,
  },
  vita_controle: {
  saida: 'controle_vita',
  unico: true,
},
};

const somenteNumeros = valor =>
  String(valor ?? '').replace(/\D/g, '');

const nomeAba = range =>
  String(range ?? '')
    .split('!')[0]
    .replace(/^'|'$/g, '')
    .trim();

function transformarLinhas(values = []) {
  const [cabecalho = [], ...linhas] = values;

  const colunas = cabecalho.map(coluna =>
    String(coluna ?? '').trim()
  );

  return linhas.map((linha, indice) => {
    const registro = {
      row_number: indice + 2,
    };

    colunas.forEach((coluna, colunaIndice) => {
      // Ignora cabeçalhos vazios
      if (!coluna) return;

      registro[coluna] =
        linha[colunaIndice] ?? '';
    });

    return registro;
  });
}

// ---------------------------------------------
// Entradas
// ---------------------------------------------

const userId = somenteNumeros(
  $('payload_webhook').first().json.phone
);

const valueRanges =
  $input.first().json.valueRanges;

if (!userId) {
  throw new Error(
    'payload_webhook não forneceu um telefone válido.'
  );
}

if (!Array.isArray(valueRanges)) {
  throw new Error(
    'A consulta não retornou valueRanges.'
  );
}

// Cria todas as saídas com valores neutros
const resultado = Object.fromEntries(
  Object.values(CONFIG).map(config => [
    config.saida,
    config.unico ? {} : [],
  ])
);

const abasRecebidas = new Set();

// ---------------------------------------------
// Processamento genérico de todas as abas
// ---------------------------------------------

for (const bloco of valueRanges) {
  const aba = nomeAba(bloco.range);
  const config = CONFIG[aba];

  // Ignora abas que não fazem parte deste payload
  if (!config) continue;

  abasRecebidas.add(aba);

  const registros = transformarLinhas(
    bloco.values
  ).filter(registro =>
    somenteNumeros(registro.user_id) === userId
  );

  resultado[config.saida] = config.unico
    ? registros[0] ?? {}
    : registros;
}

// ---------------------------------------------
// Validação
// ---------------------------------------------

const abasAusentes = Object.keys(CONFIG).filter(
  aba => !abasRecebidas.has(aba)
);

if (abasAusentes.length) {
  throw new Error(
    `Abas ausentes no batchGet: ${abasAusentes.join(', ')}`
  );
}

// ---------------------------------------------
// Output
// ---------------------------------------------

