const LIMITE_HISTORICO = 10;
const JANELA_INTERACAO_HORAS = 12;

// =====================================================
// PAYLOAD TRATADO
// =====================================================

const payload = $("payload_webhook").first().json;

// Texto atual normalizado
const texto_mensagem =
  $('Trata_mensagem').first().json.text || "";

// Data/hora atual vinda do payload
const data_atual_texto = payload.data || "";
const hora_atual_texto = payload.time || "";
const data_hora_atual_texto = `${data_atual_texto} ${hora_atual_texto}`.trim();


// =====================================================
// FUNÇÃO SIMPLES PARA DATA BR
// Formato esperado: dd/mm/yyyy HH:mm:ss
// =====================================================

function converterDataHoraBR(valor) {
  if (!valor || typeof valor !== "string") return null;

  const [data, hora = "00:00:00"] = valor.trim().split(" ");

  const [dia, mes, ano] = data.split("/").map(Number);
  const [HH = 0, MM = 0, SS = 0] = hora.split(":").map(Number);

  if (!dia || !mes || !ano) return null;

  const dataConvertida = new Date(ano, mes - 1, dia, HH, MM, SS);

  return Number.isNaN(dataConvertida.getTime()) ? null : dataConvertida;
}


// =====================================================
// HISTÓRICO
// =====================================================

let itens_historico = [];

try {
  itens_historico = $('payload_bd').first().json.eventos;
} catch {
  itens_historico = [];
}

const eventos_memoria = itens_historico
  .map(item => ({
    data_hora: item.ts,
    mensagem_usuario: item.message_in,
    resposta_vita: item.agent_reply
  }))
  .slice(-LIMITE_HISTORICO);


// =====================================================
// MEMÓRIA EM TEXTO LEGÍVEL PARA O AGENT
// =====================================================

const contexto_memoria = eventos_memoria
  .map(evento => {
    const linhas = [];

    if (evento.data_hora) {
      linhas.push(`Data: ${evento.data_hora}`);
    }

    if (evento.mensagem_usuario) {
      linhas.push(`Usuário: ${evento.mensagem_usuario}`);
    }

    if (evento.resposta_vita) {
      linhas.push(`Vita: ${evento.resposta_vita}`);
    }

    return linhas.join("\n");
  })
  .filter(Boolean)
  .join("\n\n");


// =====================================================
// ESTADO DA CONVERSA
// =====================================================

const ultimo_evento = eventos_memoria.length
  ? eventos_memoria[eventos_memoria.length - 1]
  : null;

const ultima_data_historico = ultimo_evento?.data_hora || null;

const data_hora_atual = converterDataHoraBR(data_hora_atual_texto);
const data_hora_ultima_interacao = converterDataHoraBR(ultima_data_historico);

const possui_historico = Boolean(ultima_data_historico);

const horas_desde_ultima_interacao =
  data_hora_atual && data_hora_ultima_interacao
    ? Number(
        (
          (data_hora_atual - data_hora_ultima_interacao) /
          (1000 * 60 * 60)
        ).toFixed(2)
      )
    : null;

const estado_interacao =
  possui_historico &&
  horas_desde_ultima_interacao !== null &&
  horas_desde_ultima_interacao < JANELA_INTERACAO_HORAS
    ? "interacao_em_curso"
    : "nova_interacao";

const deve_cumprimentar = estado_interacao === "nova_interacao";


// =====================================================
// OUTPUT
// =====================================================

