        nome: payload.name || null,
        data: payload.data || null,
        hora: payload.time || null,
        timestamp: payload.message_timestamp || null
      },

      memoria: {
        contexto: contexto_memoria,
        ultima_data_historico,
        limite_historico: LIMITE_HISTORICO
      },

      estado_conversa: {
        possui_historico,
        horas_desde_ultima_interacao,
        estado_interacao,
        deve_cumprimentar
      }
    }
  }
];

